def total_pedidos(pedidos):
    total = 0
    for p in pedidos:
        if p.cancelado:
            continue
        if p.valor > 1000:
            total += p.valor * 0.90
        elif p.valor > 500:
            total += p.valor * 0.95
        else:
            total += p.valor
    return total

